// prefixes: registry ROWS → nodeve.yaml's prefix map (derivation in
// src/prefixes.ts). A CURIE prefix IS a registry slug and its expansion IS that
// row's node.url — the ONE source, so the block is fully derived, never
// hand-authored. Our own namespaces (nodeve/node) are registry rows too,
// published by Amorella. Prefixes live on the root because linkml's PythonGenerator
// (the DB dump's native loader) resolves the `linkml:types` import and emits
// CurieNamespace defs for enum-meaning CURIEs only from the MAIN schema — imported
// prefixes break both. Regenerated by `generate`; drift-gated by check-prefixes.ts.
import { abs, readDoc, serializeYaml, write } from '../src/io.ts';
import { derivePrefixes } from '../src/prefixes.ts';

const prefixMap = derivePrefixes();
const doc = readDoc(abs('linkml/nodeve.yaml'));
doc.set('prefixes', prefixMap);

// mark the block machine-owned so a hand-edit is an obvious mistake, not a silent one
const pairs = (doc.contents as { items?: { key: { commentBefore?: string } }[] } | null)?.items;
const pair = pairs?.find((p) => String(p.key) === 'prefixes');
if (pair) pair.key.commentBefore = ' DERIVED from data/registry — do not edit; run `pnpm generate`';

write(abs('linkml/nodeve.yaml'), serializeYaml(doc));
console.log(`${Object.keys(prefixMap).length} prefixes → linkml/nodeve.yaml`);
